            [AppErrorCode.LABEL_SCOPE_ID_REQUIRED] = BadRequest(AppErrorCode.LABEL_SCOPE_ID_REQUIRED, "LABEL", "Phải chọn phạm vi cho nhãn theo cấp hoặc đơn vị.", "LEVEL or UNIT label scope requires scopeId."),
            [AppErrorCode.LABEL_SCOPE_ID_INVALID] = BadRequest(AppErrorCode.LABEL_SCOPE_ID_INVALID, "LABEL", "Phạm vi nhãn không hợp lệ.", "Label scopeId must be a valid ObjectId."),
            [AppErrorCode.LABEL_ENUM_CATALOG_REQUEST_REQUIRED] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_REQUEST_REQUIRED, "LABEL_ENUM", "Thiếu dữ liệu danh mục enum.", "Label enum catalog request body is missing."),
            [AppErrorCode.LABEL_ENUM_CATALOG_ID_REQUIRED] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_ID_REQUIRED, "LABEL_ENUM", "Thiếu mã danh mục enum.", "Label enum catalog id is required."),
            [AppErrorCode.LABEL_ENUM_CATALOG_NOT_FOUND] = NotFound(AppErrorCode.LABEL_ENUM_CATALOG_NOT_FOUND, "LABEL_ENUM", "Không tìm thấy danh mục enum.", "Label enum catalog does not exist, is deleted, or is outside the user's visible scope."),
            [AppErrorCode.LABEL_ENUM_CATALOG_DUPLICATE_CODE] = Status(AppErrorCode.LABEL_ENUM_CATALOG_DUPLICATE_CODE, "LABEL_ENUM", StatusCodes.Status409Conflict, "Mã danh mục enum đã tồn tại trong phạm vi này.", "Label enum catalog code is already used in the requested scope."),
            [AppErrorCode.LABEL_ENUM_CATALOG_MANAGER_REQUIRED] = Forbidden(AppErrorCode.LABEL_ENUM_CATALOG_MANAGER_REQUIRED, "LABEL_ENUM", "Cần quyền MU, ML hoặc SYSTEM_ADMIN để quản lý danh mục enum.", "SYSTEM_ADMIN, MANAGER_LEVEL, or MANAGER_UNIT is required to manage label enum catalogs."),
            [AppErrorCode.LABEL_ENUM_CATALOG_MANAGE_FORBIDDEN] = Forbidden(AppErrorCode.LABEL_ENUM_CATALOG_MANAGE_FORBIDDEN, "LABEL_ENUM", "Bạn không có quyền quản lý danh mục enum này.", "Current user cannot manage the target label enum catalog."),
            [AppErrorCode.LABEL_ENUM_CATALOG_SCOPE_MISMATCH] = Forbidden(AppErrorCode.LABEL_ENUM_CATALOG_SCOPE_MISMATCH, "LABEL_ENUM", "Phạm vi danh mục enum không khớp quyền quản lý.", "Requested label enum catalog scope does not match the manager's allowed scope."),
            [AppErrorCode.LABEL_ENUM_CATALOG_CODE_REQUIRED] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_CODE_REQUIRED, "LABEL_ENUM", "Mã danh mục enum không được trống.", "Label enum catalog code is missing or blank."),
            [AppErrorCode.LABEL_ENUM_CATALOG_CODE_INVALID] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_CODE_INVALID, "LABEL_ENUM", "Mã danh mục enum không hợp lệ.", "Label enum catalog code does not match the normalized code contract."),
            [AppErrorCode.LABEL_ENUM_CATALOG_NAME_REQUIRED] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_NAME_REQUIRED, "LABEL_ENUM", "Tên danh mục enum không được trống.", "Label enum catalog name is missing or blank."),
            [AppErrorCode.LABEL_ENUM_CATALOG_OPTION_REQUIRED] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_OPTION_REQUIRED, "LABEL_ENUM", "Danh mục enum phải có ít nhất một lựa chọn.", "Label enum catalog requires at least one active option."),
            [AppErrorCode.LABEL_ENUM_CATALOG_OPTION_INVALID] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_OPTION_INVALID, "LABEL_ENUM", "Lựa chọn enum không hợp lệ.", "Label enum option is invalid."),
            [AppErrorCode.LABEL_ENUM_CATALOG_OPTION_DUPLICATE] = BadRequest(AppErrorCode.LABEL_ENUM_CATALOG_OPTION_DUPLICATE, "LABEL_ENUM", "Mã lựa chọn enum bị trùng.", "Label enum option code is duplicated within the catalog."),
            [AppErrorCode.LABEL_ENUM_CATALOG_IN_USE] = Status(AppErrorCode.LABEL_ENUM_CATALOG_IN_USE, "LABEL_ENUM", StatusCodes.Status409Conflict, "Danh mục enum đang được nhãn hoặc biểu mẫu sử dụng.", "Label enum catalog is referenced and cannot be deleted."),

            [AppErrorCode.UPLOAD_FILE_NAME_REQUIRED] = BadRequest(AppErrorCode.UPLOAD_FILE_NAME_REQUIRED, "UPLOAD", "Tên tệp là bắt buộc.", "Upload session file name is missing."),
            [AppErrorCode.UPLOAD_SIZE_INVALID] = BadRequest(AppErrorCode.UPLOAD_SIZE_INVALID, "UPLOAD", "Dung lượng tệp không hợp lệ.", "Upload size is missing, zero, or negative."),
            [AppErrorCode.UPLOAD_FILE_TOO_LARGE] = BadRequest(AppErrorCode.UPLOAD_FILE_TOO_LARGE, "UPLOAD", "Tệp vượt quá dung lượng cho phép.", "Upload size exceeds configured max bytes."),
            [AppErrorCode.UPLOAD_ID_REQUIRED] = BadRequest(AppErrorCode.UPLOAD_ID_REQUIRED, "UPLOAD", "Thiếu mã lượt tải lên.", "Upload id is missing."),
            [AppErrorCode.UPLOAD_FILE_ID_REQUIRED] = BadRequest(AppErrorCode.UPLOAD_FILE_ID_REQUIRED, "UPLOAD", "Thiếu mã tệp.", "File id is missing."),
            [AppErrorCode.UPLOAD_FILE_NOT_FOUND] = NotFound(AppErrorCode.UPLOAD_FILE_NOT_FOUND, "UPLOAD", "Không tìm thấy tệp.", "File document or object was not found."),
            [AppErrorCode.UPLOAD_DOWNLOAD_ARGUMENTS_REQUIRED] = BadRequest(AppErrorCode.UPLOAD_DOWNLOAD_ARGUMENTS_REQUIRED, "UPLOAD", "Thiếu mã lượt tải lên hoặc tên tệp.", "Download requires upload id and file name."),
            [AppErrorCode.UPLOAD_TOKEN_MISSING] = BadRequest(AppErrorCode.UPLOAD_TOKEN_MISSING, "UPLOAD", "Thiếu thông tin xác nhận tải lên.", "TUS finalize request is missing Upload-Token header."),
            [AppErrorCode.UPLOAD_TOKEN_INVALID] = BadRequest(AppErrorCode.UPLOAD_TOKEN_INVALID, "UPLOAD", "Thông tin xác nhận tải lên không hợp lệ.", "TUS finalize upload token cannot be validated."),
            [AppErrorCode.UPLOAD_SOURCE_ID_MISSING] = BadRequest(AppErrorCode.UPLOAD_SOURCE_ID_MISSING, "UPLOAD", "Thiếu mã nguồn của tệp tải lên.", "Validated upload token has no source id."),
            [AppErrorCode.UPLOAD_SIZE_COMMITTED_INVALID] = BadRequest(AppErrorCode.UPLOAD_SIZE_COMMITTED_INVALID, "UPLOAD", "Dung lượng tệp tải lên không hợp lệ.", "Committed TUS stream has invalid size."),
        };

    public static AppErrorDescriptor Get(AppErrorCode code)
        => Descriptors.TryGetValue(code, out var descriptor)
            ? descriptor
            : Descriptors[AppErrorCode.COMMON_INTERNAL_ERROR];

    private static AppErrorDescriptor BadRequest(AppErrorCode code, string service, string message, string description)
        => Status(code, service, StatusCodes.Status400BadRequest, message, description);

    private static AppErrorDescriptor Forbidden(AppErrorCode code, string service, string message, string description)
        => Status(code, service, StatusCodes.Status403Forbidden, message, description);

    private static AppErrorDescriptor NotFound(AppErrorCode code, string service, string message, string description)
        => Status(code, service, StatusCodes.Status404NotFound, message, description);

    private static AppErrorDescriptor Status(AppErrorCode code, string service, int status, string message, string description)
        => new(code, service, status, message, description);
}
